//! The compiled scripted events — the `ds:0x5183` slot dispatch, the
//! suspend/re-enter contract, and host-call plumbing. GAM-80: scripts
//! are `script::evNN` functions generated by `xgen`, so these tests
//! drive the *shipped* scripts through `Vm::from_image` state — no
//! bytecode is assembled.

mod common;

use supremacy::game::{self, Call, Ctx, NullHost, Rng, State, Vm, VmHost, TAB_BASE};

/// A recording host — captures every [`Call`] the ops emit.
struct Rec(Vec<Call>);

impl VmHost for Rec {
    fn svc(&mut self, call: Call) -> u16 {
        self.0.push(call);
        0
    }
}

/// Build a context over owned parts; `run` closures against it.
struct Rig {
    vm: Vm,
    st: State,
    rng: Rng,
    host: Rec,
    files: supremacy::platform::MemFs,
}

impl Rig {
    /// Rig over the shipped image — the compiled scripts and their
    /// `ds:` flag cells live there.
    fn new() -> Self {
        Self {
            vm: Vm::from_image(&supremacy::img::image()),
            st: State::new(),
            rng: Rng::new(0x42),
            host: Rec(Vec::new()),
            files: supremacy::platform::MemFs::new(),
        }
    }

    fn ctx(&mut self) -> Ctx<'_> {
        Ctx {
            vm: &mut self.vm,
            st: &mut self.st,
            rng: &mut self.rng,
            host: &mut self.host,
            files: &mut self.files,
        }
    }

    /// `game::run` on this rig's context.
    fn run(&mut self, idx: u16) -> u16 {
        game::run(&mut self.ctx(), idx)
    }

    /// Byte write through the VM regions.
    fn set8(&mut self, a: u16, v: u8) {
        let c = self.ctx();
        c.vm.w8(c.st, a, v);
    }

    /// Word write through the VM regions.
    fn set16(&mut self, a: u16, v: u16) {
        let c = self.ctx();
        c.vm.w16(c.st, a, v);
    }

    /// Byte read through the VM regions.
    fn get8(&mut self, a: u16) -> u8 {
        let c = self.ctx();
        c.vm.r8(c.st, a)
    }

    /// Point event slot `idx` at script `si` — a real compiled
    /// script address, or an unknown one for the no-op path.
    fn event(&mut self, idx: u16, si: u16) {
        let a = usize::from(TAB_BASE) + usize::from(idx) * 4;
        self.vm.low[a..a + 2].copy_from_slice(&si.to_le_bytes());
    }
}

#[test]
fn regions_split_at_the_save_block() {
    let mut r = Rig {
        vm: Vm::new(),
        ..Rig::new()
    };
    r.set8(0x1234, 0xAB); // low
    r.set8(0x8150, 0xCD); // inside the save block
    r.set8(0x9DD0, 0xEF); // hi
    assert_eq!(r.get8(0x1234), 0xAB);
    assert_eq!(r.st.byte(0x8150), 0xCD);
    assert_eq!(r.get8(0x9DD0), 0xEF);
    r.set16(0x9CC3, 0x1122); // straddles block end → hi start
    assert_eq!(r.st.byte(0x9CC3), 0x22);
    let c = r.ctx();
    assert_eq!(c.vm.r16(c.st, 0x9CC3), 0x1122);
}

#[test]
fn shipped_slots_suspend_on_fresh_state() {
    // Fresh `ds:` cells hold 0, so every script's first guard suspends
    // — `run` reports the op index it stopped at (`≥ 1`), never `0`.
    let mut r = Rig::new();
    for i in 0..30 {
        assert!(r.run(i) >= 1, "slot {i} must run at least its guard");
    }
    // An `si` that is not a compiled script runs nothing.
    r.event(0, 0x1234);
    assert_eq!(r.run(0), 0);
}

#[test]
fn guard_rerun_then_completed_script() {
    // ev00 — `wait_b 0x81FF` (done-latch: runs while 0),
    // `wait_eq_b 0x8200==0xFF`, two prints, `set_flag 0x81FF=0xFF`:
    // the classic guard+action rule.
    let mut r = Rig::new();
    r.set8(0x81FF, 0);
    assert_eq!(r.run(0), 2); // the `0x8200` guard blocks
    r.set8(0x8200, 0xFF);
    assert_eq!(r.run(0), 6); // whole rule ran — re-entry semantics kept
    assert_eq!(r.run(0), 1); // done-latch now set — suspends at once
    assert_eq!(r.host.0[0], Call::Chan(0x8A5B, 0));
    assert_eq!(r.host.0[1], Call::Chan(0x8A3B, 0x1F));
    assert_eq!(r.host.0[2], Call::Sound(0xC));
    let c = r.ctx();
    assert_eq!(c.vm.r16(c.st, 0x91C2), 2); // two prints → two records
    assert_eq!(c.vm.r8(c.st, 0x91E8), 0xFF);
}

#[test]
fn double_wait_progresses_one_step_at_a_time() {
    // ev23 — two `wait_b` guards, nothing else.
    let mut r = Rig::new();
    r.set8(0x822E, 0);
    assert_eq!(r.run(23), 2); // waits while `0x91F0` is 0
    r.set8(0x822E, 0xFF);
    assert_eq!(r.run(23), 1); // the done-latch blocks first
    r.set8(0x822E, 0);
    r.set8(0x91F0, 0xFF);
    assert_eq!(r.run(23), 3);
}

#[test]
fn delay_counts_down_across_reruns() {
    // ev07 — `delay 0x8212` sits behind three guards; the countdown
    // ticks once per entry while nonzero.
    let mut r = Rig::new();
    r.set8(0x8210, 0);
    r.set8(0x91CD, 0);
    r.set8(0x820A, 0xFF); // wait_b set=true → continues when nonzero
    r.set16(0x8212, 2);
    assert_eq!(r.run(7), 4); // 2 → 1
    assert_eq!(r.run(7), 4); // 1 → 0
    assert!(r.run(7) > 4); // expired — runs into the body
}

#[test]
fn rand_planet_stores_a_record() {
    // ev04 — behind two guards, `rand_planet` picks into `[0x81EE]`.
    let mut r = Rig {
        st: common::gsim::galaxy(),
        ..Rig::new()
    };
    r.set8(0x8207, 0);
    r.set8(0x81FE, 0xFF); // wait_b set=true → continues when nonzero
    assert!(r.run(4) >= 3); // rand_planet ran (then wait_kind gates)
    let c = r.ctx();
    let sel = c.vm.r16(c.st, 0x81EE);
    let (base, n) = (c.st.word(game::REC_BASE), c.st.word(game::REC_COUNT));
    assert!((sel - base).is_multiple_of(0x3A) && (sel - base) / 0x3A < n);
}

#[test]
fn dialog_and_menu_reach_host() {
    // ev08 — the dialog op ships as word `0x7C` (`cs:0x79C4`); GAM-80's
    // compiled form calls `vimpl::dialog` for either label.
    let mut r = Rig {
        st: common::gsim::galaxy(),
        ..Rig::new()
    };
    r.set8(0x8214, 0);
    r.set8(0x91CD, 0);
    r.set16(0x91BC, 0x07E1);
    assert!(r.run(8) >= 4); // rand_planet ran
    let c = r.ctx();
    assert_ne!(c.vm.r16(c.st, 0x81EE), 0); // a record was selected
}

#[test]
fn tick_dispatches_script_events() {
    let mut st = common::gsim::galaxy();
    let n = u8::try_from(st.word(game::REC_TOTAL)).unwrap();
    st.set_byte(game::SEQ, 0x38 + 2 * n - 1);
    let tick = common::gsim::step(&mut st, &mut Rng::new(1), 's');
    assert!(matches!(tick, game::Tick::Script(_)));
    assert_eq!(NullHost.svc(Call::Menu), 0); // sink drops host calls
}
